(()=>{'use strict';const $=id=>document.getElementById(id),box=$('feedback-inbox');if(!box)return;const E=window.ProjectFeedbackExport;let items=[],summary={},generation=0,ready=false,loading=false;const controls=['fb-target','fb-kind','fb-rating','fb-search'],exports=['fb-export-csv','fb-export-json','fb-export-report'];const filters=()=>Object.fromEntries(controls.map(id=>[id.replace('fb-',''),$(id).value]));const filtered=()=>{const f=filters(),q=f.search.trim().toLowerCase();return items.filter(r=>(!f.target||r.target===f.target)&&(!f.kind||r.kind===f.kind)&&(!f.rating||Number(r.rating)===Number(f.rating))&&(!q||[r.id,E.reference(r.id),r.title,r.message,r.steps,r.os,r.version,r.device,r.build].join(' ').toLowerCase().includes(q)))};
function node(tag,text,cls){const e=document.createElement(tag);e.textContent=text;if(cls)e.className=cls;return e}
function metrics(){for(const id of['feedback-metrics','feedback-overview']){const area=$(id);area.replaceChildren();const data=[['Reports',summary.reports||0],['Issues',summary.issues||0],['Feedback',summary.feedback||0]];for(const target of['helper','launcher']){const r=(summary.ratings||[]).find(x=>x.target===target);data.push([E.experience(target),r?.count?Number(r.average).toFixed(2)+' / 5':'Not rated yet',r?`${r.count} ratings`:'0 ratings'])}for(const [label,value,note]of data){const cell=node('div','','feedback-admin-metric');cell.append(node('small',label),node('strong',value));if(note)cell.append(node('small',note));area.append(cell)}}}
function render(){const rows=filtered();box.replaceChildren();$('feedback-inbox-status').textContent=`${rows.length.toLocaleString()} of ${items.length.toLocaleString()} reports · newest first`;for(const r of rows){const article=document.createElement('details');article.className='feedback-inbox-item';const top=document.createElement('summary');top.append(node('small',`${E.reference(r.id)} · ${E.time(r.created_at)} · ${E.experience(r.target)} · ${r.kind} · ${r.rating}/5`),node('strong',r.title));article.append(top);const details=document.createElement('dl');for(const [label,value]of[['Status',r.status],['Operating system',[r.os,r.version].filter(Boolean).join(' ')],['Device',r.device],['App / launcher',r.build]]){details.append(node('dt',label),node('dd',value||'Not specified'))}article.append(details,node('h4','Description'),node('p',r.message));if(r.steps)article.append(node('h4','Steps to reproduce'),node('p',r.steps));box.append(article)}if(!rows.length)box.append(node('p',items.length?'No reports match your filters.':'No reports yet. New submissions will appear here.','muted'));exports.forEach(id=>$(id).disabled=!ready||loading)}
async function load(){const token=sessionStorage.getItem('gtav-admin-token-v2');if(!token||loading)return;const current=++generation;loading=true;ready=false;exports.forEach(id=>$(id).disabled=true);$('feedback-inbox-status').textContent='Loading all reports…';try{let offset=0,snapshot=null,all=[];do{const params=new URLSearchParams({admin:'1',offset:String(offset)});if(snapshot!==null)params.set('snapshot',snapshot);const response=await fetch('/api/feedback?'+params,{headers:{'X-Admin-Token':token},cache:'no-store'});if(!response.ok)throw Error();const d=await response.json();if(current!==generation)return;all.push(...d.items);snapshot=d.snapshot;summary=d.summary;offset=d.nextOffset;$('feedback-inbox-status').textContent=`Loaded ${all.length.toLocaleString()} of ${Number(d.total).toLocaleString()} reports…`}while(offset!==null);items=all;ready=true;metrics()}catch{if(current===generation){$('feedback-inbox-status').textContent='Could not load reports. Refresh to try again. Exports are disabled to avoid incomplete results.'}}finally{if(current===generation){loading=false;if(ready)render()}}}
function download(ext,type,body){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([body],{type}));const stamp=new Date().toISOString().replace(/[:.]/g,'-').slice(0,19);a.href=url;a.download=`gtav-feedback-${stamp}Z.${ext}`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000)}
$('fb-export-csv').onclick=()=>{if(ready&&!loading)download('csv','text/csv;charset=utf-8',E.csv(filtered()))};$('fb-export-json').onclick=()=>{if(ready&&!loading)download('json','application/json;charset=utf-8',E.json(filtered(),summary,filters()))};$('fb-export-report').onclick=()=>{if(ready&&!loading)download('html','text/html;charset=utf-8',E.html(filtered(),summary,filters()))};controls.forEach(id=>$(id).addEventListener('input',()=>{if(ready)render()}));$('refresh-feedback').onclick=load;document.querySelector('[data-tab="feedback"]')?.addEventListener('click',load);$('open-feedback-inbox').onclick=()=>document.querySelector('[data-tab="feedback"]').click();window.addEventListener('project-admin-unlocked',load);window.addEventListener('project-admin-refreshed',load);$('refresh-all').addEventListener('click',load);$('lock-out').addEventListener('click',()=>{generation++;items=[];summary={};ready=false;loading=false;box.replaceChildren();$('feedback-metrics').replaceChildren();$('feedback-overview').replaceChildren();$('feedback-inbox-status').textContent='Unlock the dashboard to load reports.';exports.forEach(id=>$(id).disabled=true)});if(sessionStorage.getItem('gtav-admin-token-v2')&&!$('dashboard').hidden)load();})();
(()=>{if(!document.getElementById('dashboard')||document.getElementById('admin-mods-loader'))return;const css=document.createElement('link');css.rel='stylesheet';css.href='admin-mods.css?v=20261029modsadmin3';css.id='admin-mods-style';document.head.append(css);const galleryCss=document.createElement('link');galleryCss.rel='stylesheet';galleryCss.href='admin-mods-gallery-v1.css?v=20261029gallery1';galleryCss.id='admin-mods-gallery-style';document.head.append(galleryCss);const script=document.createElement('script');script.src='admin-mods.js?v=20261029modsadmin3';script.id='admin-mods-loader';script.async=false;document.head.append(script);const gallery=document.createElement('script');gallery.src='admin-mods-gallery-v1.js?v=20261029gallery1';gallery.id='admin-mods-gallery-loader';gallery.async=false;document.head.append(gallery)})();
